const module = angular.module("irtech.netcity.school.maintenance",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"netcity.common.menu", "ngFileUpload", "ui.tree", "irtech.netcity.common", "irtech.netcity.ui-components"
	]);

import { MaintenanceCtrl } from "./maintenanceCtrl.js";
import { MaintenanceRepository } from "./repository.js";

module
	.controller("MaintenanceCtrl", MaintenanceCtrl)
	.factory("maintenanceRepository", ($http, $dialogs, $alerts, $q) => new MaintenanceRepository($http, $dialogs, $alerts, $q))
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.otherwise({
				templateUrl: "/static/dist/app/school/maintenance/template.html",
				controller: "MaintenanceCtrl as ctrl"
			});
		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});



