"use strict";

class BaseRepository {
	constructor($http, $dialogs, $alerts) {
		this.$http = $http;
		this.$dialogs = $dialogs;
		this.$alerts = $alerts;
	}

	handleError(response) {
		$(document).trigger("closeProcessing");
		if (response.status === 401) {
			let authError = response.headers("auth-error");
			if (authError === "SessionExpired") {
				$.show.message(language.Generic.Common.kTimeOutOccured4Ajax).then(() => window.location.pathname = "/");
			}
			else {
				alert(language.Generic.Common.kErrPageAccess);
			}
		} else {

			let errorText = '';

			if (response.data.message) {
				errorText += response.data.message;
			}

			if (response.data.details) {
				errorText += ', ' + response.data.details;
			}

			$.show.error(errorText);
		}
		return Promise.reject(response);
	}
}

module.exports = { BaseRepository };


