"use strict";

import * as Rights from "approot/global/references/rights.js";
import * as Specialty from "./maintainSpecialty.js";

class MaintenanceCtrl {
	constructor ($scope, pageContext, $appLoader, $q, $alerts, maintenanceRepository, changeTracker) {
		this.language = language;
		this.scope = $scope;
		pageContext.title = language.Generic.Maintenance.kTitleMaintenance;
		pageContext.parent = null;

		this.readonly = appContext.readOnly || !appContext.hasAnyRight([Rights.arProfileEditSchoolInfo]);
		this.state = {
			 dataReady: false
		};
		this.data = {
			 maintenance: {}
		};
		this.specialty = Specialty;

		this.appLoader = $appLoader;
		this.q = $q;
		this.alerts = $alerts;
		this.repository = maintenanceRepository;
		this.changeTracker = changeTracker;

		this.load();
	}

	// загрузка данных
	load() {
		this.state.dataReady = false;

		const getMaintenance = this.repository.getMaintenance().then((maintenance) => {
			this.data.maintenance = maintenance;
		});

		const queries = this.q.all([getMaintenance]);

		queries.then(() => {
			this.state.dataReady = true;
			this.changeTracker.clearDataChanges();
			this.appLoader.hide();
		});
	}

	checkDefects(defectologist, isStaff) {
		if (defectologist.specialty.id !== this.specialty.defectologist)
			return true;

		var oligophren = _.chain(this.data.maintenance).find(x => x.specialty.id === this.specialty.oligophren).value();
		var surdo = _.chain(this.data.maintenance).find(x => x.specialty.id === this.specialty.surdo).value();
		var tiflo = _.chain(this.data.maintenance).find(x => x.specialty.id === this.specialty.tiflo).value();

		if (isStaff && defectologist.specNumber1 === 0 && (oligophren.specNumber1 !== 0 || surdo.specNumber1 !== 0 || tiflo.specNumber1 !== 0))
			return false;

		if (!isStaff && defectologist.specNumber2 === 0 && (oligophren.specNumber2 !== 0 || surdo.specNumber2 !== 0 || tiflo.specNumber2 !== 0))
			return false;

		return true;
	}

	checkMedicals(med, isStaff) {
		if (med.specialty.id !== this.specialty.med)
			return true;

		var pediatr = _.chain(this.data.maintenance).find(x => x.specialty.id === this.specialty.pediatr).value();
		var neurolog = _.chain(this.data.maintenance).find(x => x.specialty.id === this.specialty.neurolog).value();
		var ophthalmologist = _.chain(this.data.maintenance).find(x => x.specialty.id === this.specialty.ophthalmologist).value();
		var audiologist = _.chain(this.data.maintenance).find(x => x.specialty.id === this.specialty.audiologist).value();

		if (isStaff && med.specNumber1 === 0 && (pediatr.specNumber1 !== 0 || neurolog.specNumber1 !== 0 || ophthalmologist.specNumber1 !== 0 || audiologist.specNumber1 !== 0))
			return false;

		if (!isStaff && med.specNumber2 === 0 && (pediatr.specNumber2 !== 0 || neurolog.specNumber2 !== 0 || ophthalmologist.specNumber2 !== 0 || audiologist.specNumber2 !== 0))
			return false;

		return true;
	}

	save(valid) {
		if (!valid) {
			return;
		}

		var defectologist = _.chain(this.data.maintenance).find(x => x.specialty.id === this.specialty.defectologist).value();
		var med = _.chain(this.data.maintenance).find(x => x.specialty.id === this.specialty.med).value();
		if (!(this.checkDefects(defectologist, true) &&
			this.checkDefects(defectologist, false) &&
			this.checkMedicals(med, true) &&
			this.checkMedicals(med, false))) {
			return;
		}

		const processing = $.show.processing();
		this.repository.save(this.data.maintenance).then(() => {
			//this.load();
			processing.close();
			this.state.dataReady = true;
			this.changeTracker.clearDataChanges();
			this.alerts.success(language.Generic.Common.kDataSaved);
		},
		() => { processing.close(); });
	}
}
MaintenanceCtrl.$inject = ["$scope", "pageContext", "$appLoader", "$q", "$alerts", "maintenanceRepository", "changeTracker"];
module.exports = { MaintenanceCtrl };



